// Rules the brief requires, stated as intent (not read off the code).
const TERMINAL = ['shipped', 'cancelled', 'failed'];
const STATUSES = ['none', 'draft', 'placed', 'paid', 'shipped', 'cancelled', 'failed'];
const same = (a, b) => ['status', 'items', 'charges', 'refunds', 'pending'].every((k) => a[k] === b[k]);

export const stateInvariants = [
  { name: 'status-known', pred: (s) => STATUSES.includes(s.status) },
  { name: 'items-in-range', pred: (s) => s.items >= 0 && s.items <= 3 },
  { name: 'charged-at-most-once', pred: (s) => s.charges <= 1 },
  { name: 'refunded-at-most-once', pred: (s) => s.refunds <= 1 },
  { name: 'refund-only-after-charge', pred: (s) => s.refunds <= s.charges },
  { name: 'charged-iff-left-draft-via-place',
    pred: (s) => (s.charges === 1) === (['placed', 'paid', 'shipped', 'failed'].includes(s.status) || (s.status === 'cancelled' && s.refunds === 1)) },
  { name: 'charged-orders-have-items', pred: (s) => s.charges === 0 || s.items >= 1 },
  { name: 'pending-only-while-placed', pred: (s) => (s.pending === 1) === (s.status === 'placed') && s.pending <= 1 },
  { name: 'refund-only-when-cancelled', pred: (s) => s.refunds === 0 || s.status === 'cancelled' },
  { name: 'nothing-before-create', pred: (s) => s.status !== 'none' || (s.items === 0 && s.charges === 0 && s.refunds === 0 && s.pending === 0) },
];

export const transitionInvariants = [
  { name: 'terminal-accepts-nothing', pred: (pre, a, d, post) => !TERMINAL.includes(pre.status) || same(pre, post) },
  { name: 'ships-only-when-paid', pred: (pre, a, d, post) => !(post.status === 'shipped' && pre.status !== 'shipped') || pre.status === 'paid' },
  { name: 'charge-only-on-place-with-items',
    pred: (pre, a, d, post) => post.charges === pre.charges || (a === 'PLACE' && pre.status === 'draft' && pre.items >= 1) },
  { name: 'refund-exactly-on-paid-cancel',
    pred: (pre, a, d, post) => (post.refunds > pre.refunds) === (a === 'CANCEL' && pre.status === 'paid') },
  { name: 'cancel-refused-while-placed', pred: (pre, a, d, post) => !(a === 'CANCEL' && pre.status === 'placed') || same(pre, post) },
  { name: 'items-change-only-in-draft', pred: (pre, a, d, post) => pre.items === post.items || (pre.status === 'draft' && post.status === 'draft') },
];

export default { stateInvariants, transitionInvariants };

