'use strict';

// SAM v2 strict-profile spec of one order's lifecycle, derived from
// src/host.impl.ts. Orders are independent, so one order (plus its pending
// charge effect) is the whole stateful core. status 'none' = not yet created.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_ITEMS = 3;
const MAX_CHARGES = 2;
const INITIAL_STATE = { status: 'none', items: 0, charges: 0, refunds: 0, pending: 0 };

const intent = (domain = [{}]) => ({ action: (data = {}) => ({ ...data }), schema: {}, domain });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      items: { type: 'number' },
      charges: { type: 'number' },
      refunds: { type: 'number' },
      pending: { type: 'number' },
    },
    actions: {
      CREATE: intent(),
      ADD_ITEM: intent(),
      REMOVE_ITEM: intent(),
      PLACE: intent(),
      RETRY_PAYMENT: intent(),
      SHIP: intent(),
      CANCEL: intent(),
      COMPLETE_CHARGE: {
        action: (data = {}) => ({ ...data }),
        schema: { outcome: { type: 'string' } },
        domain: [{ outcome: 'ok' }, { outcome: 'failed' }],
      },
    },
    acceptors: {
      CREATE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'none') return reject('order already exists');
        next.status = 'draft';
        unchanged('items', 'charges', 'refunds', 'pending');
      },
      ADD_ITEM: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'draft') return reject('order is not a draft');
        if (model.items >= MAX_ITEMS) return reject('cart-limit');
        next.items = model.items + 1;
        unchanged('status', 'charges', 'refunds', 'pending');
      },
      REMOVE_ITEM: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'draft') return reject('order is not a draft');
        if (model.items === 0) return reject('draft is empty');
        next.items = model.items - 1;
        unchanged('status', 'charges', 'refunds', 'pending');
      },
      PLACE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'draft') return reject('order is not a draft');
        if (model.items === 0) return reject('draft is empty');
        next.status = 'placed';
        next.charges = model.charges + 1;
        next.pending = model.pending + 1;
        unchanged('items', 'refunds');
      },
      RETRY_PAYMENT: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'declined') return reject('order is not declined');
        next.status = 'placed';
        next.charges = model.charges + 1;
        next.pending = model.pending + 1;
        unchanged('items', 'refunds');
      },
      SHIP: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'paid') return reject('order is not paid');
        next.status = 'shipped';
        unchanged('items', 'charges', 'refunds', 'pending');
      },
      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'draft') {
          next.status = 'cancelled';
          unchanged('items', 'charges', 'refunds', 'pending');
          return;
        }
        if (model.status === 'paid') {
          next.status = 'cancelled';
          next.refunds = model.refunds + 1;
          unchanged('items', 'charges', 'pending');
          return;
        }
        if (model.status === 'placed') return reject('no-cancel-while-placed');
        return reject('cancel not allowed');
      },
      COMPLETE_CHARGE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.pending === 0) return reject('no pending charge');
        next.pending = model.pending - 1;
        if (model.status === 'placed') {
          if (proposal.outcome === 'ok') next.status = 'paid';
          else next.status = model.charges < MAX_CHARGES ? 'declined' : 'failed';
        } else unchanged('status');
        unchanged('items', 'charges', 'refunds');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  CREATE: (data = {}) => intents.CREATE(data),
  ADD_ITEM: (data = {}) => intents.ADD_ITEM(data),
  REMOVE_ITEM: (data = {}) => intents.REMOVE_ITEM(data),
  PLACE: (data = {}) => intents.PLACE(data),
  RETRY_PAYMENT: (data = {}) => intents.RETRY_PAYMENT(data),
  SHIP: (data = {}) => intents.SHIP(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  COMPLETE_CHARGE: (data = {}) => intents.COMPLETE_CHARGE(data),
};

module.exports = { instance, init, actions, getState, setState };

