test('hold and release', async () => {
  const h = await createHost();
  assert.equal((await h.hold('a')).ok, false);
  assert.equal((await h.release('a')).ok, false);
  await h.create('a'); await h.addItem('a');
  assert.equal((await h.hold('a')).ok, false);
  await h.place('a');
  assert.equal((await h.hold('a')).ok, false);
  await h.completeEffect((await h.pendingEffects())[0].id, 'ok');
  assert.equal((await h.release('a')).ok, false);
  assert.deepEqual(await h.hold('a'), { ok: true });
  assert.deepEqual(await h.order('a'), view('paid', 1, 1, 0, true));
  assert.equal((await h.hold('a')).ok, false);
  assert.equal((await h.ship('a')).ok, false);
  assert.deepEqual(await h.release('a'), { ok: true });
  assert.equal((await h.release('a')).ok, false);
  assert.equal((await h.ship('a')).ok, true);
  assert.deepEqual(await h.order('a'), view('shipped', 1, 1, 0, false));
  assert.equal((await h.hold('a')).ok, false);
});

test('held paid order can be cancelled and is no longer held', async () => {
  const h = await createHost();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  await h.completeEffect((await h.pendingEffects())[0].id, 'ok');
  await h.hold('a');
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.order('a'), view('cancelled', 1, 1, 1, false));
  assert.equal((await h.release('a')).ok, false);
  assert.equal((await h.hold('a')).ok, false);
});

